// Maps each raw subject value (as stored per-artwork, including compound
// and duplicate tags) to the canonical filter tag(s) it should match. A
// painting tagged with a compound value like "טבע וטבע דומם" will match
// BOTH "טבע" and "טבע דומם" filters. "דומם" merges into "טבע דומם". Only
// the canonical tags on the right ever appear as filter options.
const SUBJECT_FILTER_MAP = {
  "דומם": ["טבע דומם"],
  "טבע ודמויות": ["טבע", "דמויות"],
  "טבע וטבע דומם": ["טבע", "טבע דומם"],
  "עיר ויהדות": ["עיר", "יהדות"],
};
function subjectFilterTags(rawSubject) {
  return SUBJECT_FILTER_MAP[rawSubject] || [rawSubject];
}


