// Only artworks with a verified, matched photo — used for Full Gallery and
// Discover so catalog entries with no image yet (currently 4001-4048) don't
// show up as empty/broken cards. They reappear automatically here the
// moment hasVerifiedImage becomes true for them.
const VISIBLE_ARTWORKS = ARTWORKS.filter((a) => a.hasVerifiedImage);

/* ---------------------------------------------------------
   IMAGE WITH FALLBACK
--------------------------------------------------------- */
function ArtImage({ sources, alt, natural }) {
  const list = Array.isArray(sources) ? sources.filter(Boolean) : [sources];
  const [i, setI] = useState(0);

  if (i >= list.length) {
    return (
      <div
        style={{
          aspectRatio: natural ? undefined : "1 / 1",
          minHeight: natural ? 240 : undefined,
          background: "#E3DCCB",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "#A79A85",
        }}
      >
        <ImageOff size={22} />
      </div>
    );
  }
  return (
    <img
      key={list[i]}
      src={list[i]}
      alt={alt}
      loading="lazy"
      onError={() => setI((n) => n + 1)}
      style={
        natural
          ? { width: "100%", maxHeight: "70vh", objectFit: "contain", display: "block", background: "#E3DCCB" }
          : { width: "100%", aspectRatio: "1 / 1", objectFit: "cover", display: "block", background: "#E3DCCB" }
      }
    />
  );
}

/* ---------------------------------------------------------
   MUSEUM PLACARD
--------------------------------------------------------- */
function Placard({ art, onClick }) {
  const { t, tv, displayFont, bodyFont } = useLang();
  return (
    <div style={{ cursor: "pointer" }} onClick={onClick}>
      <ArtImage sources={[localImageUrl(art.id), art.thumbUrl, art.imageUrl]} alt={art.title} />
      <div style={{ paddingTop: 10 }}>
        <div
          style={{
            fontFamily: "'Roboto Mono', monospace",
            fontSize: 10,
            letterSpacing: "0.04em",
            color: "#A66B33",
            marginBottom: 4,
            direction: "ltr",
            textAlign: "right",
          }}
        >
          {t("catalogNo")} {art.id} — {art.year || t("unknownDate")}
          {!art.hasVerifiedImage && <span style={{ color: "#8B4A3D" }}> · {t("imageMissing")}</span>}
        </div>
        <div
          style={{
            fontFamily: displayFont,
            fontSize: 15,
            color: "#221D17",
            lineHeight: 1.35,
          }}
        >
          {art.title}
        </div>
        <div
          style={{
            fontFamily: bodyFont,
            fontSize: 12,
            color: "#6B5B4F",
            marginTop: 3,
          }}
        >
          {tv(SUBJECT_TR, art.subject)} · {art.technique}
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   LIGHTBOX
--------------------------------------------------------- */
function bigImageUrls(art) {
  // Try several Drive URL formats/sizes in order — different endpoints get
  // rate-limited or blocked independently, so falling back across all of
  // them maximizes the odds one actually loads.
  const idMatch = (art.thumbUrl || "").match(/id=([^&]+)/);
  const id = idMatch ? idMatch[1] : null;
  const urls = [];
  if (id) {
    urls.push(`https://drive.google.com/thumbnail?id=${id}&sz=w2000`);
    urls.push(`https://drive.google.com/thumbnail?id=${id}&sz=w1000`);
    urls.push(`https://lh3.googleusercontent.com/d/${id}=w1600`);
  }
  urls.push(art.imageUrl);
  urls.push(art.thumbUrl);
  return urls;
}

function Lightbox({ art, onClose, onNext, onPrev }) {
  const { t, tv, displayFont, bodyFont } = useLang();

  useEffect(() => {
    if (!art) return;
    function handleKey(e) {
      if (e.key === "Escape") onClose();
      else if (e.key === "ArrowLeft") {
        // In RTL reading order, left arrow moves to the next item; in LTR, to previous.
        document.dir === "rtl" ? onNext && onNext() : onPrev && onPrev();
      } else if (e.key === "ArrowRight") {
        document.dir === "rtl" ? onPrev && onPrev() : onNext && onNext();
      }
    }
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [art, onNext, onPrev, onClose]);

  if (!art) return null;
  const navBtnStyle = {
    position: "absolute",
    top: "50%",
    transform: "translateY(-50%)",
    background: "#221D17cc",
    color: "#F7F3EA",
    border: "none",
    borderRadius: "50%",
    width: 40,
    height: 40,
    cursor: "pointer",
    fontSize: 18,
    zIndex: 51,
  };
  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed",
        inset: 0,
        background: "#1A1712ee",
        zIndex: 50,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 24,
      }}
    >
      {onPrev && (
        <button onClick={(e) => { e.stopPropagation(); onPrev(); }} style={{ ...navBtnStyle, left: 16 }} aria-label="previous">
          ‹
        </button>
      )}
      {onNext && (
        <button onClick={(e) => { e.stopPropagation(); onNext(); }} style={{ ...navBtnStyle, right: 16 }} aria-label="next">
          ›
        </button>
      )}
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#F7F3EA",
          maxWidth: 780,
          width: "100%",
          maxHeight: "90vh",
          overflow: "auto",
          borderRadius: 3,
          position: "relative",
        }}
      >
        <ArtImage key={art.id} sources={[localImageUrl(art.id), ...bigImageUrls(art)]} alt={art.title} natural />
        <div style={{ padding: 24 }}>
          <div style={{ fontFamily: "'Roboto Mono', monospace", fontSize: 11, color: "#A66B33", direction: "ltr", textAlign: "right", marginBottom: 6 }}>
            {t("catalogNo")} {art.id}
          </div>
          <div style={{ fontFamily: displayFont, fontSize: 24, color: "#221D17", marginBottom: 10 }}>
            {art.title}
          </div>
          <div style={{ fontFamily: bodyFont, fontSize: 14, color: "#3E3A33", lineHeight: 1.9 }}>
            <div>{t("fieldYear")}: {art.year || t("unknown")}</div>
            <div>{t("fieldSubject")}: {tv(SUBJECT_TR, art.subject)}</div>
            <div>{t("fieldTechnique")}: {art.technique}</div>
            <div>{t("fieldSize")}: {art.sizeDesc}</div>
          </div>
        </div>
        <button
          onClick={onClose}
          style={{
            position: "absolute",
            top: 16,
            left: 16,
            background: "#221D17cc",
            color: "#F7F3EA",
            border: "none",
            borderRadius: "50%",
            width: 36,
            height: 36,
            cursor: "pointer",
          }}
        >
          <X size={18} style={{ margin: "auto" }} />
        </button>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   NAV
--------------------------------------------------------- */
function Nav({ page, setPage }) {
  const [open, setOpen] = useState(false);
  const { t, displayFont } = useLang();
  const links = [
    ["home", t("navHome")],
    ["gallery", t("navGallery")],
    ["selected", t("navSelected")],
    ["discover", t("navDiscover")],
    ["contact", t("navContact")],
  ];
  return (
    <div style={{ position: "sticky", top: 0, zIndex: 20, background: "#EFE9DDf2", backdropFilter: "blur(6px)", borderBottom: "1px solid #C9BFA9" }}>
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "18px 24px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <button
          onClick={() => setPage("home")}
          style={{ background: "none", border: "none", cursor: "pointer", fontFamily: displayFont, fontSize: 21, fontWeight: 700, color: "#221D17" }}
        >
          {t("siteName")}
        </button>
        <div style={{ display: "flex", gap: 26 }} className="nav-links">
          {links.map(([key, label]) => (
            <button
              key={key}
              onClick={() => setPage(key)}
              style={{
                background: "none",
                border: "none",
                cursor: "pointer",
                fontFamily: "'Assistant', sans-serif",
                fontWeight: 600,
                fontSize: 14,
                color: page === key ? "#3E4A3B" : "#6B5B4F",
                borderBottom: page === key ? "1px solid #3E4A3B" : "1px solid transparent",
                paddingBottom: 3,
              }}
            >
              {label}
            </button>
          ))}
        </div>
        <button onClick={() => setOpen(!open)} className="nav-toggle" style={{ background: "none", border: "none", cursor: "pointer", display: "none" }}>
          {open ? <X size={20} /> : <Menu size={20} />}
        </button>
      </div>
      {open && (
        <div style={{ padding: "0 24px 18px", display: "flex", flexDirection: "column", gap: 14 }}>
          {links.map(([key, label]) => (
            <button
              key={key}
              onClick={() => { setPage(key); setOpen(false); }}
              style={{ background: "none", border: "none", textAlign: "right", cursor: "pointer", fontFamily: "'Assistant', sans-serif", fontSize: 14, color: page === key ? "#3E4A3B" : "#6B5B4F" }}
            >
              {label}
            </button>
          ))}
        </div>
      )}
      <style>{`@media (max-width: 720px) { .nav-links { display: none !important; } .nav-toggle { display: block !important; } }`}</style>
    </div>
  );
}

